						)
					)
				}
				destinationPoints.none { it.isFinal } && finalCoordinates != null -> {
					destinationPoints + MapDestinationPoint(
						name = finalDestination,
						latitude = finalCoordinates.latitude,
						longitude = finalCoordinates.longitude,
						isFinal = true
					)
				}
				else -> destinationPoints
			}

			val points = pointsWithFinal.ifEmpty {
				val fallbackCoordinates = resolveTripCoordinates(trip.destination)
				if (fallbackCoordinates != null) {
					listOf(
						MapDestinationPoint(
							name = trip.destination,
							latitude = fallbackCoordinates.latitude,
							longitude = fallbackCoordinates.longitude,
							isFinal = true
						)
					)
				} else {
					emptyList()
				}
			}

			val routePath = routeRepository.getDrivingRoute(points.map { DestinationCoordinates(it.latitude, it.longitude) })
				?.map { RoutePathPoint(it.latitude, it.longitude) }
				?: emptyList()

