			val centerPoint = points.firstOrNull { it.isFinal } ?: originPoint
			_uiState.update {
				it.copy(
					mapLatitude = centerPoint?.latitude ?: originPoint?.latitude,
					mapLongitude = centerPoint?.longitude ?: originPoint?.longitude,
					mapDestinationLabel = centerPoint?.name ?: trip.destination,
					mapPoints = points,
					routePath = routePath,
					tripDestinations = effectiveDestinations
				)
			}
		}
	}

	private suspend fun resolveTripCoordinates(destination: String) =
		locationRepository.getCoordinatesForDestination(destination)

	private fun currentUtcDateStartMillis(): Long {
		return Instant.now()
			.atZone(ZoneOffset.UTC)
			.toLocalDate()
			.atStartOfDay(ZoneOffset.UTC)
			.toInstant()
			.toEpochMilli()
	}
}
